import{_ as o,l as s,o as e,c as i,v as r,p as d,x as t,d as l,i as c,S as E}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"哈佛与冯·诺依曼","description":"","frontmatter":{"title":"哈佛与冯·诺依曼","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/harvard-von-neumann.md","filePath":"cs/harvard-von-neumann.md","lastUpdated":1789023840000}'),h={name:"cs/harvard-von-neumann.md"};function p(A,a,m,u,_,C){const n=s("Mermaid");return e(),i("div",null,[a[1]||(a[1]=r('<h1 id="哈佛与冯·诺依曼" tabindex="-1">哈佛与冯·诺依曼 <a class="header-anchor" href="#哈佛与冯·诺依曼" aria-label="Permalink to &quot;哈佛与冯·诺依曼&quot;">​</a></h1><div class="epigraph"><p>程序都是存储器里的指令；差别在取指与访数是否抢同一套口。冯·诺依曼共用，哈佛分开，仍是存储程序。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；von Neumann, First Draft of a Report on the EDVAC, 1945 整理</footer></div><p>上一课<a href="/cs/stored-program">存储程序</a>钉死了指令编码成比特、PC 去取。它已点名哈佛与冯·诺依曼差在端口。本课不重讲 PC 初值，也不从操作系统进程另起。缺口是把<strong>两个口还是一个口</strong>写成组成选择：后课单周期图常画分开的指令存储器与数据存储器，那是哈佛式教学模型。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>冯·诺依曼：同一可寻址空间、同一套总线，取指与 <code>lw</code>/<code>sw</code> 争带宽——瓶颈。哈佛：指令口与数据口并行，允许一拍同时取指与访存。缺口不是「程序是否在内存」，而是端口与地址空间是否统一。</p><p>现代 CPU：程序员看见统一虚址（冯·诺依曼），片上 I-cache 与 D-cache 分开（哈佛微结构）。MCU 常真哈佛。本课钉这一层对照，不把 Cache 一致性提前。</p><h3 id="哈佛不是「不能当数据读指令」" tabindex="-1">哈佛不是「不能当数据读指令」 <a class="header-anchor" href="#哈佛不是「不能当数据读指令」" aria-label="Permalink to &quot;哈佛不是「不能当数据读指令」&quot;">​</a></h3><p>分开的是口。若指令阵列可写，仍能自修改，只是走另一端口或经同步。RISC-V 教学默认不要靠自修改；<code>fence.i</code> 很后。把哈佛理解成「指令不是比特」，会与上一课冲突。</p><p><span class="marginnote">Patterson/Hennessy 单周期用两个存储器方框，避免一拍双端口冲突。EDVAC 草案是统一存储。本课不把哈佛大学标记指令格式当内容。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画两种：共用存储器与 MUX 的取指/访数；双端口或两片阵列。单周期若坚持冯·诺依曼单口，取指与 <code>lw</code> 无法同拍，必须多周期或牺牲 \\(T\\)。</p>',11)),(e(),d(E,null,{default:t(()=>[c(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SP%5B%22%E5%AD%98%E5%82%A8%E7%A8%8B%E5%BA%8F%22%5D%20--%3E%20VN%5B%22%E7%BB%9F%E4%B8%80%E5%8F%A3%EF%BC%9A%E4%BA%89%E7%94%A8%22%5D%0A%20%20SP%20--%3E%20HV%5B%22%E6%8C%87%E4%BB%A4%E5%8F%A3%E4%B8%8E%E6%95%B0%E6%8D%AE%E5%8F%A3%22%5D%0A%20%20HV%20--%3E%20TEACH%5B%22%E6%95%99%E5%AD%A6%E5%8D%95%E5%91%A8%E6%9C%9F%E4%B8%A4%E6%A1%86%22%5D%0A%20%20TEACH%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%8C%87%E4%BB%A4%E5%AD%97%E6%AE%B5%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课指令格式切的是取出来的字，与口无关。总线课会再把「口」收成系统总线或交叉开关。组成主干：看见两个方框时，想到的是哈佛端口，不是两个 ISA。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲修改代码的安全含义、不把 Harvard architecture 的历史机型清单列完。不讨论 GPU 的分离存储。</p><p>后课默认：程序仍是内存中的指令比特；教学数据通路可以指令/数据分口。下一课按 RISC-V 切 32 位字段。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>存储程序共通；哈佛/冯·诺依曼差在端口与争用。</li><li>程序员模型常统一空间，微结构可分 I/D。</li><li>指令仍是比特，下一课切字段。</li><li>出处：Patterson and Hennessy, COD (RISC-V)；von Neumann, EDVAC 草案, 1945。</li></ul>',7))])}const D=o(h,[["render",p]]);export{f as __pageData,D as default};
